    [3324]={name="Ghostly Mantle",quality=3,ilvl=27,reqLevel=18,sourceType="quest_reward",instructions="Reward from the quest 'Deathstalkers in Shadowfang'.",zone="Shadowfang Keep",questName="Deathstalkers in Shadowfang",lore="In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence."},
    [3344]={name="Captain Sander's Sash",quality=2,ilvl=15,reqLevel=10,sourceType="quest_reward",instructions="Reward from the quest 'Captain Sander's Hidden Treasure'. The quest is in Westfall. Objective: Locate Captain Sanders' chest and open it for your reward. Provided item:.",zone="Westfall",questName="Captain Sander's Hidden Treasure",lore="Sure enough, deep within the Old Jug there is another clue to Sander's treasure."},
    [3345]={name="Silk Wizard Hat",quality=2,ilvl=37,reqLevel=32,sourceType="world_drop",instructions="Drops from Syndicate Magus.",zone="Arathi Highlands",npc="Syndicate Magus"},
