    [15104]={name="Wingborne Boots",quality=2,ilvl=39,reqLevel=30,sourceType="quest_reward",instructions="Reward from the quest 'Malin's Request'. Pick it over the other reward choices. Starts with Skuerto in Stormwind City. Objective: Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.",zone="Arathi Highlands",questName="Malin's Request",lore="Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, of that I've no doubt."},
    [15114]={name="Rigid Cape",quality=2,ilvl=19,reqLevel=14,sourceType="world_drop",instructions="World drop around level 14-20."},
