    [18693]={name="Shivery Handwraps",quality=3,ilvl=62,reqLevel=57,sourceType="boss_drop",instructions="Drops from Ras Frostwhisper.",zone="Scholomance",npc="Ras Frostwhisper",lore="A human lord who traded his life for undeath and became a lich in Scholomance. Killing him takes a blade specifically made to sever the bargain."},
